import 'package:dio/dio.dart';
import 'package:meilisearch/meilisearch.dart';
import 'package:test/test.dart';

void main() {
  group('Network models', () {
    test('Network.fromMap parses self, leader, remotes, shards', () {
      final json = <String, Object?>{
        'self': 'ms-0',
        'leader': 'ms-0',
        'remotes': <String, Object?>{
          'ms-1': <String, Object?>{
            'url': 'http://localhost:7701',
            'searchApiKey': 'sk',
            'writeApiKey': 'wk',
          },
        },
        'shards': <String, Object?>{
          'shard-a': <String, Object?>{
            'remotes': <Object?>['ms-0', 'ms-1'],
          },
        },
      };

      final n = Network.fromMap(json);

      expect(n.self, 'ms-0');
      expect(n.leader, 'ms-0');
      expect(n.remotes, isNotNull);
      expect(n.remotes!['ms-1']!.url, 'http://localhost:7701');
      expect(n.remotes!['ms-1']!.searchApiKey, 'sk');
      expect(n.remotes!['ms-1']!.writeApiKey, 'wk');

      expect(n.shards, isNotNull);
      expect(n.shards!['shard-a']!.remotes, ['ms-0', 'ms-1']);
      expect(n.shards!['shard-a']!.addRemotes, isNull);
      expect(n.shards!['shard-a']!.removeRemotes, isNull);
    });

    test('Remote.toPatchMap is sparse', () {
      expect(
        const Remote(url: 'http://a').toPatchMap(),
        {'url': 'http://a'},
      );
      expect(
        Remote(
          url: 'http://a',
          searchApiKey: 's',
          writeApiKey: 'w',
        ).toPatchMap(),
        {
          'url': 'http://a',
          'searchApiKey': 's',
          'writeApiKey': 'w',
        },
      );
    });

    test('Shard.toPatchMap is sparse', () {
      expect(
        const Shard(addRemotes: ['a']).toPatchMap(),
        {
          'addRemotes': ['a']
        },
      );
      expect(
        const Shard(remotes: ['x'], removeRemotes: ['y']).toPatchMap(),
        {
          'remotes': ['x'],
          'removeRemotes': ['y'],
        },
      );
    });

    test('UpdateNetworkOptions builds partial PATCH bodies', () {
      expect(UpdateNetworkOptions().toPatchMap(), isEmpty);

      expect(
        UpdateNetworkOptions(self: 'node-1').toPatchMap(),
        {'self': 'node-1'},
      );

      expect(
        UpdateNetworkOptions(leader: null).toPatchMap(),
        {'leader': null},
      );

      expect(
        UpdateNetworkOptions(
          remotes: {
            'r1': const Remote(url: 'http://one'),
            'r2': null,
          },
        ).toPatchMap(),
        {
          'remotes': <String, Object?>{
            'r1': {'url': 'http://one'},
            'r2': null,
          },
        },
      );

      expect(
        UpdateNetworkOptions(
          shards: {
            's1': const Shard(addRemotes: ['a']),
          },
        ).toPatchMap(),
        {
          'shards': <String, Object?>{
            's1': {
              'addRemotes': ['a']
            },
          },
        },
      );
    });
  });

  group('MeiliSearchClient network', () {
    test('getNetwork uses GET /network', () async {
      final captured = <RequestOptions>[];
      final client = MeiliSearchClient.withCustomDio(
        'http://unit.test',
        apiKey: 'masterKey',
        interceptors: [
          InterceptorsWrapper(
            onRequest: (options, handler) {
              captured.add(options);
              handler.resolve(
                Response<Map<String, Object?>>(
                  requestOptions: options,
                  statusCode: 200,
                  data: <String, Object?>{
                    'self': 'ms-0',
                    'remotes': <String, Object?>{},
                  },
                ),
              );
            },
          ),
        ],
      );

      final net = await client.getNetwork();

      expect(captured, hasLength(1));
      expect(captured.single.path, '/network');
      expect(captured.single.method, 'GET');
      expect(net.self, 'ms-0');
      expect(net.remotes, isNotNull);
      expect(net.remotes, isEmpty);
    });

    test('updateNetwork uses PATCH /network with body', () async {
      RequestOptions? last;
      final client = MeiliSearchClient.withCustomDio(
        'http://unit.test',
        apiKey: 'masterKey',
        interceptors: [
          InterceptorsWrapper(
            onRequest: (options, handler) {
              last = options;
              handler.resolve(
                Response<Map<String, Object?>>(
                  requestOptions: options,
                  statusCode: 200,
                  data: <String, Object?>{
                    'self': 'x',
                    'remotes': <String, Object?>{},
                  },
                ),
              );
            },
          ),
        ],
      );

      await client.updateNetwork(UpdateNetworkOptions(self: 'x'));

      expect(last, isNotNull);
      expect(last!.path, '/network');
      expect(last!.method, 'PATCH');
      expect(last!.data, {'self': 'x'});
    });

    test('addRemote builds remotes patch entry', () async {
      Map<String, Object?>? data;
      final client = MeiliSearchClient.withCustomDio(
        'http://unit.test',
        apiKey: 'masterKey',
        interceptors: [
          InterceptorsWrapper(
            onRequest: (options, handler) {
              data = options.data as Map<String, Object?>?;
              handler.resolve(
                Response<Map<String, Object?>>(
                  requestOptions: options,
                  statusCode: 200,
                  data: <String, Object?>{'remotes': <String, Object?>{}},
                ),
              );
            },
          ),
        ],
      );

      await client.addRemote(
        'peer',
        const Remote(url: 'http://peer:7700', searchApiKey: 'sk'),
      );

      expect(data, {
        'remotes': {
          'peer': {'url': 'http://peer:7700', 'searchApiKey': 'sk'},
        },
      });
    });

    test('removeRemote nulls remote entry', () async {
      Map<String, Object?>? data;
      final client = MeiliSearchClient.withCustomDio(
        'http://unit.test',
        apiKey: 'masterKey',
        interceptors: [
          InterceptorsWrapper(
            onRequest: (options, handler) {
              data = options.data as Map<String, Object?>?;
              handler.resolve(
                Response<Map<String, Object?>>(
                  requestOptions: options,
                  statusCode: 200,
                  data: <String, Object?>{'remotes': <String, Object?>{}},
                ),
              );
            },
          ),
        ],
      );

      await client.removeRemote('peer');

      expect(data, {
        'remotes': {'peer': null},
      });
    });

    test('addRemotesToShard and removeRemotesFromShard', () async {
      final bodies = <Map<String, Object?>?>[];
      final client = MeiliSearchClient.withCustomDio(
        'http://unit.test',
        apiKey: 'masterKey',
        interceptors: [
          InterceptorsWrapper(
            onRequest: (options, handler) {
              bodies.add(options.data as Map<String, Object?>?);
              handler.resolve(
                Response<Map<String, Object?>>(
                  requestOptions: options,
                  statusCode: 200,
                  data: <String, Object?>{'shards': <String, Object?>{}},
                ),
              );
            },
          ),
        ],
      );

      await client.addRemotesToShard('shard-1', ['a', 'b']);
      await client.removeRemotesFromShard('shard-1', ['a']);

      expect(bodies[0], {
        'shards': {
          'shard-1': {
            'addRemotes': ['a', 'b']
          },
        },
      });
      expect(bodies[1], {
        'shards': {
          'shard-1': {
            'removeRemotes': ['a']
          },
        },
      });
    });

    test('updateNetwork rejects empty patch', () async {
      final client = MeiliSearchClient.withCustomDio(
        'http://unit.test',
        apiKey: 'masterKey',
      );

      expect(
        () => client.updateNetwork(UpdateNetworkOptions()),
        throwsArgumentError,
      );
    });
  });
}

import 'package:meilisearch/meilisearch.dart';
import 'package:test/test.dart';

import 'utils/books.dart';
import 'utils/books_data.dart';
import 'utils/client.dart';
import 'utils/wait_for.dart';

void main() {
  final openAiKeyValue = openAiKey;

  group('Search', () {
    setUpClient();
    late String uid;
    late MeiliSearchIndex index;

    setUp(() {
      uid = randomUid();
    });

    group('Books', () {
      setUp(() async {
        index = await createBooksIndex(uid: uid);
      });

      test('map', () async {
        //search
        //if deserialization fails it will throw
        final castedResult =
            await index.search('').asSearchResult().map(BookDto.fromMap);
        //test
        expect(castedResult.hits, everyElement(isA<BookDto>()));
      });

      test('with basic query', () async {
        final result = await index.search('prience'); // with typo

        expect(result.hits, hasLength(2));
      });

      test('with basic query with no q', () async {
        final result = await index.search(null);

        expect(result.hits, hasLength(books.length));
      });

      test('with basic query with an empty string q=""', () async {
        final result = await index.search('');

        expect(result.hits, hasLength(books.length));
      });

      test('with basic query with phrase search', () async {
        final result = await index.search('coco "harry"');

        expect(result.hits, hasLength(1));
      });

      test('Show ranking score details', () async {
        final res = await index
            .search(
              'The',
              SearchQuery(
                showRankingScore: true,
                showRankingScoreDetails: true,
                attributesToHighlight: ['*'],
                showMatchesPosition: true,
              ),
            )
            .asSearchResult()
            .mapToContainer();

        final attributeMatcher = isA<MeiliRankingScoreDetailsAttributeRule>()
            .having((p0) => p0.src, 'src', allOf(isNotNull, isNotEmpty))
            .having((p0) => p0.score, 'score', isNotNull)
            .having((p0) => p0.order, 'order', isNotNull)
            .having((p0) => p0.queryWordDistanceScore, 'queryWordDistanceScore',
                isNotNull)
            .having((p0) => p0.attributeRankingOrderScore,
                'attributeRankingOrderScore', isNotNull);

        final attributeRankMatcher =
            isA<MeiliRankingScoreDetailsAttributeRankRule>()
                .having((p0) => p0.src, 'src', allOf(isNotNull, isNotEmpty))
                .having((p0) => p0.score, 'score', isNotNull)
                .having((p0) => p0.order, 'order', isNotNull);

        final wordPositionMatcher =
            isA<MeiliRankingScoreDetailsWordPositionRule>()
                .having((p0) => p0.src, 'src', allOf(isNotNull, isNotEmpty))
                .having((p0) => p0.score, 'score', isNotNull)
                .having((p0) => p0.order, 'order', isNotNull);

        final sortMatcher = isA<MeiliRankingScoreDetailsSortRule>()
            .having((p0) => p0.src, 'src', allOf(isNotNull, isNotEmpty))
            .having((p0) => p0.order, 'order', isNotNull)
            .having((p0) => p0.value, 'value', isNotNull);

        final sortRulesMatcher =
            isA<Map<String, MeiliRankingScoreDetailsSortRule>>().having(
          (p0) => p0.values,
          'sort values',
          everyElement(sortMatcher),
        );

        final wordsMatcher = isA<MeiliRankingScoreDetailsWordsRule>()
            .having((p0) => p0.src, 'src', allOf(isNotNull, isNotEmpty))
            .having((p0) => p0.score, 'score', isNotNull)
            .having((p0) => p0.order, 'order', isNotNull)
            .having((p0) => p0.matchingWords, 'matchingWords', isNotNull)
            .having((p0) => p0.maxMatchingWords, 'maxMatchingWords', isNotNull);

        final exactnessMatcher = isA<MeiliRankingScoreDetailsExactnessRule>()
            .having((p0) => p0.src, 'src', allOf(isNotNull, isNotEmpty))
            .having((p0) => p0.score, 'score', isNotNull)
            .having((p0) => p0.order, 'order', isNotNull)
            .having(
              (p0) => p0.matchType,
              'matchType',
              allOf(isNotNull, isNotEmpty),
            );

        final typoMatcher = isA<MeiliRankingScoreDetailsTypoRule>()
            .having((p0) => p0.src, 'src', allOf(isNotNull, isNotEmpty))
            .having((p0) => p0.score, 'score', isNotNull)
            .having((p0) => p0.order, 'order', isNotNull)
            .having((p0) => p0.typoCount, 'typoCount', isNotNull)
            .having((p0) => p0.maxTypoCount, 'maxTypoCount', isNotNull);

        final proximityMatcher = isA<MeiliRankingScoreDetailsProximityRule>()
            .having((p0) => p0.src, 'src', allOf(isNotNull, isNotEmpty))
            .having((p0) => p0.score, 'score', isNotNull)
            .having((p0) => p0.order, 'order', isNotNull);

        final rankingScoreDetailsMatcher = isA<MeiliRankingScoreDetails>()
            .having((p0) => p0.src, 'src', allOf(isNotNull, isNotEmpty))
            .having((p0) => p0.attribute, 'attribute',
                anyOf(isNull, attributeMatcher))
            .having((p0) => p0.attributeRank, 'attributeRank',
                anyOf(isNull, attributeRankMatcher))
            .having((p0) => p0.wordPosition, 'wordPosition',
                anyOf(isNull, wordPositionMatcher))
            .having((p0) => p0.words, 'words', wordsMatcher)
            .having((p0) => p0.exactness, 'exactness', exactnessMatcher)
            .having((p0) => p0.typo, 'typo', typoMatcher)
            .having((p0) => p0.proximity, 'proximity', proximityMatcher)
            .having((p0) => p0.sort, 'sort', anyOf(isNull, sortRulesMatcher))
            .having((p0) => p0.customRules, 'customRules',
                allOf(isNotNull, isEmpty));

        expect(res.hits.length, 4);

        expect(
          res.hits,
          everyElement(
            isA<MeiliDocumentContainer<Map<String, dynamic>>>()
                .having(
                  (p0) => p0.parsed,
                  'parsed',
                  isNotEmpty,
                )
                .having(
                  (p0) => p0.src,
                  'src',
                  isNotEmpty,
                )
                .having(
                  (p0) => p0.rankingScore,
                  'rankingScore',
                  isNotNull,
                )
                .having(
                  (p0) => p0.rankingScoreDetails,
                  'rankingScoreDetails',
                  rankingScoreDetailsMatcher,
                ),
          ),
        );
      });

      test('Show performance details', () async {
        final result = await index.search(
          'prince',
          SearchQuery(showPerformanceDetails: true),
        );

        expect(result.performanceDetails, isNotNull);
        expect(result.performanceDetails, isA<Map<String, dynamic>>());
        expect(result.performanceDetails, isNotEmpty);
      });

      test('performanceDetails is null when not requested', () async {
        final result = await index.search('prince');

        expect(result.performanceDetails, isNull);
      });

      test('performanceDetails is null when set to false', () async {
        final result = await index.search(
          'prince',
          SearchQuery(showPerformanceDetails: false),
        );

        expect(result.performanceDetails, isNull);
      });

      group('with', () {
        test('offset parameter', () async {
          final result =
              await index.search('', SearchQuery(limit: 3, offset: 10));

          expect(result.hits, isEmpty);
        });

        test('limit parameter', () async {
          final result = await index.search('', SearchQuery(limit: 3));

          expect(result.hits, hasLength(3));
        });

        test('cropLength parameter', () async {
          final result = await index.search(
            'Alice In Wonderland',
            SearchQuery(
              attributesToCrop: ["title"],
              cropLength: 2,
            ),
          );

          expect(
            result.hits[0]['_formatted']['title'],
            equals('Alice In…'),
          );
        });

        test('searches with default cropping parameters', () async {
          final result = await index.search(
            'prince',
            SearchQuery(
              attributesToCrop: ['*'],
              cropLength: 2,
            ),
          );

          expect(
            result.hits[0]['_formatted']['title'],
            equals('…Petit Prince'),
          );
        });

        test('searches with custom cropMarker', () async {
          final result = await index.search(
            'prince',
            SearchQuery(
              attributesToCrop: ['*'],
              cropLength: 1,
              cropMarker: '[…] ',
            ),
          );

          expect(result.hits[0]['_formatted']['title'], equals('[…] Prince'));
        });

        test('searches with custom highlight tags', () async {
          final result = await index.search(
            'blood',
            SearchQuery(
              attributesToHighlight: ['*'],
              highlightPreTag: '<mark>',
              highlightPostTag: '</mark>',
            ),
          );

          expect(
            result.hits[0]['_formatted']['title'],
            equals('Harry Potter and the Half-<mark>Blood</mark> Prince'),
          );
        });

        test('searches with matching strategy last', () async {
          final result = await index.search(
            'the to',
            SearchQuery(
              matchingStrategy: MatchingStrategy.last,
            ),
          );

          expect(
            result.hits.last['title'],
            equals('Harry Potter and the Half-Blood Prince'),
          );
        });

        test('searches with matching strategy all', () async {
          final result = await index.search(
            'the to',
            SearchQuery(
              matchingStrategy: MatchingStrategy.all,
            ),
          );

          expect(
            result.hits.last['title'],
            equals('The Hitchhiker\'s Guide to the Galaxy'),
          );
        });

        test('searches with matching strategy as null if not set', () async {
          final result = await index.search('the to');

          expect(
            result.hits.last['title'],
            equals('Harry Potter and the Half-Blood Prince'),
          );
        });

        test('filter parameter', () async {
          await index
              .updateFilterableAttributes(['tag']).waitFor(client: client);

          final result =
              await index.search('prince', SearchQuery(filter: '"tag" = Tale'));

          expect(result.hits, hasLength(1));
        });

        test('filter parameter is null', () async {
          var index = await createBooksIndex();
          await index
              .updateFilterableAttributes(['tag']).waitFor(client: client);

          var result = await index.search(
            'The Hobbit',
            SearchQuery(filterExpression: 'tag'.toMeiliAttribute().isNull()),
          );

          expect(result.hits, hasLength(1));
          expect(result.hits.first["book_id"], equals(9999));
        });

        test('filter parameter with spaces', () async {
          await index
              .updateFilterableAttributes(['tag']).waitFor(client: client);

          final result = await index.search(
            'prince',
            SearchQuery(
              filter: 'tag = "Epic fantasy"',
            ),
          );

          expect(result.hits, hasLength(1));
        });

        test('facetStats parameter', () async {
          final indexWithNumbers = client.index(randomUid());
          final docs = List.generate(
            10,
            (index) => <String, Object?>{
              'id': 100 - index,
              'year': (index * 2) + 2010,
            },
          );
          await indexWithNumbers.addDocuments(docs).waitFor(client: client);
          await indexWithNumbers
              .updateFilterableAttributes(['year']).waitFor(client: client);

          var result =
              await indexWithNumbers.search('', SearchQuery(facets: ['*']));

          expect(result.hits, hasLength(10));
          expect(result.facetStats?['year']?.min, 2010);
          expect(result.facetStats?['year']?.max, 2028);
        });

        group('facet search', () {
          setUp(() async {
            await index.updateFilterableAttributes(
              ['tag', 'book_id'],
            ).waitFor(client: client);
          });

          test('basic', () async {
            final facetSearchRes = await index.facetSearch(
              FacetSearchQuery(
                facetName: 'tag',
                facetQuery: 't',
              ),
            );

            expect(facetSearchRes.facetHits, hasLength(1));
            expect(facetSearchRes.facetHits[0].count, 2);
            expect(facetSearchRes.facetHits[0].value, "Tale");
            expect(facetSearchRes.facetQuery, "t");
          });

          test('With additional search params', () async {
            final facetSearchRes = await index.facetSearch(
              FacetSearchQuery(facetName: 'tag', facetQuery: 't', q: 'hobbit'),
            );

            expect(facetSearchRes.facetHits, hasLength(0));
            expect(facetSearchRes.facetQuery, "t");
          });
        });

        test('filter parameter with number', () async {
          await index.updateFilterableAttributes(
            ['tag', 'book_id'],
          ).waitFor(client: client);

          final result = await index.search(
            '',
            SearchQuery(
              filter: 'book_id < 100 AND tag = Tale',
            ),
          );

          expect(result.hits, hasLength(1));
        });

        test('filter parameter with array', () async {
          await index
              .updateFilterableAttributes(['tag']).waitFor(client: client);

          final result =
              await index.search('prince', SearchQuery(filter: ['tag = Tale']));

          expect(result.hits, hasLength(1));
        });

        test('filter parameter with multiple array', () async {
          await index
              .updateFilterableAttributes(['tag']).waitFor(client: client);

          final result = await index.search(
            'prince',
            SearchQuery(filter: [
              ['tag = Tale', 'tag = Tale'],
              'tag = Tale'
            ]),
          );

          expect(result.hits, hasLength(1));
        });

        test('facetDistributions parameter', () async {
          await index
              .updateFilterableAttributes([ktag]).waitFor(client: client);

          final result =
              await index.search('prince', SearchQuery(facets: ['*']));

          expect(result.hits, hasLength(2));
          expect(result.facetDistribution?[ktag]?.length, 2);
        });

        test('Sort parameter', () async {
          await index
              .updateSettings(IndexSettings(sortableAttributes: [
                'title'
              ], rankingRules: [
                'words',
                'sort',
                'typo',
                'proximity',
                'attribute',
                'exactness'
              ]))
              .waitFor(client: client);

          final result =
              await index.search('prince', SearchQuery(sort: ['title:asc']));

          expect(result.hits, hasLength(2));
          expect(result.hits[0]['book_id'], 4);
        });

        group('finite-pagination query params', () {
          test('with basic query', () async {
            final result = await index
                .search('pri', SearchQuery(page: 1))
                .asPaginatedResult();

            expect(result.totalPages, 1);
          });

          test('accesses fields from Searchable', () async {
            final result = await index
                .search('pri', SearchQuery(page: 1))
                .asPaginatedResult();

            expect(result.hits.length, greaterThanOrEqualTo(1));
            expect(result.totalPages, 1);
          });

          test('with mixed pagination query params', () async {
            final result = await index
                .search('pri', SearchQuery(page: 1, limit: 10))
                .asPaginatedResult();

            expect(result.totalPages, 1);
          });
        });
      });

      test('use rankingScoreThreshold', () async {
        final res = await index
            .search(
              'The',
              SearchQuery(
                showRankingScore: true,
                rankingScoreThreshold: 0.9,
              ),
            )
            .asSearchResult()
            .mapToContainer();

        expect(res.hits.length, 3);

        expect(
          res.hits,
          everyElement(
            isA<MeiliDocumentContainer<Map<String, dynamic>>>().having(
              (p0) => p0.rankingScore,
              'rankingScore',
              greaterThanOrEqualTo(0.9),
            ),
          ),
        );
      });
    });

    group('Nested Books', () {
      setUp(() async {
        index = await createNestedBooksIndex(uid: uid);
      });

      test('searches within nested content with no parameters', () async {
        final response = await index.search('An awesome');

        expect(response.hits[0], {
          "id": 5,
          "title": 'The Hobbit',
          "info": {
            "comment": 'An awesome book',
            "reviewNb": 900,
          },
        });
      });

      test(
          'searches on nested content with searchable on specific nested field',
          () async {
        await index.updateSearchableAttributes(
          ['title', 'info.comment'],
        ).waitFor(client: client);

        final response = await index.search('An awesome');

        expect(response.hits[0], {
          "id": 5,
          "title": 'The Hobbit',
          "info": {
            "comment": 'An awesome book',
            "reviewNb": 900,
          },
        });
      });
      group('attributesToSearchOn', () {
        setUp(() async {
          await index.updateSearchableAttributes(
            ['title', 'info.comment'],
          ).waitFor(client: client);
        });

        test('empty result', () async {
          var response = await index.search(
            'An awesome',
            SearchQuery(attributesToSearchOn: ['title']),
          );

          expect(response.hits, isEmpty);
        });

        test('non-empty result', () async {
          var response = await index.search(
            'An awesome',
            SearchQuery(attributesToSearchOn: ['info.comment']),
          );

          expect(response.hits[0], {
            "id": 5,
            "title": 'The Hobbit',
            "info": {
              "comment": 'An awesome book',
              "reviewNb": 900,
            },
          });
        });
      });

      test('searches on nested content with content with sort', () async {
        await index
