class _CleanupSpyClient extends TestMeiliSearchClient {
  _CleanupSpyClient() : super('http://localhost:7700');

  int getTaskCallCount = 0;
  final Map<int, int> _pollsByTaskUid = <int, int>{};

  @override
  Future<Task> deleteIndex(String uid) async {
    usedIndexes.remove(uid);

    return Task(
      uid: uid.hashCode & 0x7fffffff,
      indexUid: uid,
      status: 'enqueued',
      type: 'indexDeletion',
    );
  }

  @override
  Future<Task> getTask(int uid) async {
    getTaskCallCount++;
    final pollCount = (_pollsByTaskUid[uid] ?? 0) + 1;
    _pollsByTaskUid[uid] = pollCount;

    return Task(
      uid: uid,
      status: pollCount >= 2 ? 'succeeded' : 'enqueued',
      type: 'indexDeletion',
    );
  }
}

void main() {
  group('TestMeiliSearchClient resource cleanup', () {
    test('disposeUsedResources polls index deletion tasks until completion',
        () async {
      final client = _CleanupSpyClient();
      client.usedIndexes.addAll({'movies', 'books'});

      await client.disposeUsedResources();

      expect(
        client.getTaskCallCount,
        greaterThan(0),
        reason:
            'disposeUsedResources() should wait for async delete tasks to complete.',
      );
    });
  });
}

import 'package:collection/collection.dart';
import 'package:dio/dio.dart';
import 'package:meilisearch/meilisearch.dart';

import '../utils/wait_for.dart';

class TestMeiliSearchClient extends MeiliSearchClient {
  TestMeiliSearchClient(
    super.serverUrl, [
    super.apiKey,
    super.connectTimeout,
    super.adapter,
    super.interceptors,
  ]);

  factory TestMeiliSearchClient.withCustomDio(
    String serverUrl, {
    String? apiKey,
    Duration? connectTimeout,
    HttpClientAdapter? adapter,
    List<Interceptor>? interceptors,
  }) =>
      TestMeiliSearchClient(
        serverUrl,
        apiKey,
        connectTimeout,
        adapter,
        interceptors,
      );

  final usedIndexes = <String>{};
  final usedKeys = <String>{};

  @override
  MeiliSearchIndex index(String uid, {bool deleteWhenDone = true}) {
    if (deleteWhenDone) {
      usedIndexes.add(uid);
    }
    return super.index(uid);
  }

  @override
  Future<Task> createIndex(String uid, {String? primaryKey}) {
    usedIndexes.add(uid);
    return super.createIndex(uid, primaryKey: primaryKey);
  }

  @override
  Future<Map<String, Object?>> getRawIndex(
    String uid, {
    bool deleteWhenDone = true,
  }) {
    return super.getRawIndex(uid).then((value) {
      if (deleteWhenDone) {
        usedIndexes.add(uid);
      }
      return value;
    }).onError((error, stackTrace) {
      usedIndexes.remove(uid);
      throw error!;
    });
  }

  @override
  Future<Task> swapIndexes(
    List<SwapIndex> param, {
    bool deleteWhenDone = true,
  }) {
    if (deleteWhenDone) {
      usedIndexes.addAll(param.map((e) => e.indexes).flattened);
    }
    return super.swapIndexes(param);
  }

  @override
  Future<Key> createKey({
    required List<String> indexes,
    required List<String> actions,
    DateTime? expiresAt,
    String? description,
    String? uid,
    bool deleteWhenDone = true,
  }) {
    return super
        .createKey(
      expiresAt: expiresAt,
      description: description,
      uid: uid,
      indexes: indexes,
      actions: actions,
    )
        .then((value) {
      if (deleteWhenDone) {
        usedKeys.add(value.key);
      }
      return value;
    });
  }

  @override
  Future<bool> deleteKey(String key) {
    usedKeys.remove(key);
    return super.deleteKey(key);
  }

  Future<void> disposeUsedResources() async {
    await Future.wait([
      _deleteUsedIndexes(),
      _deleteUsedKeys(),
    ]);
  }

  Future<void> _deleteUsedIndexes() async {
    final indexUids = usedIndexes.toSet();
    final deletedOrMissing = <String>{};
    final deletionTasks = <Task>[];
    final taskUidToIndexUid = <int, String>{};

    for (final indexUid in indexUids) {
      try {
        final task = await deleteIndex(indexUid);
        deletionTasks.add(task);
        if (task.uid != null) {
          taskUidToIndexUid[task.uid!] = indexUid;
        }
      } on MeiliSearchApiException catch (error) {
        if (error.code == 'index_not_found') {
          deletedOrMissing.add(indexUid);
          continue;
        }
        rethrow;
      }
    }

    if (deletionTasks.isNotEmpty) {
      final completedTasks = await Future.wait(
        deletionTasks.map(
          (task) => task.waitFor(
            client: this,
            throwFailed: false,
          ),
        ),
      );

      for (final task in completedTasks) {
        final indexUid = task.indexUid ??
            (task.uid != null ? taskUidToIndexUid[task.uid!] : null);

        if (indexUid == null) {
          continue;
        }

        if (task.status == 'succeeded' ||
            task.error?.code == 'index_not_found') {
          deletedOrMissing.add(indexUid);
          continue;
        }

        throw MeiliSearchApiException(
          'Task (${task.uid}) failed, error: ${task.error}',
          code: task.error?.code,
          link: task.error?.link,
          type: task.error?.type,
        );
      }
    }

    usedIndexes.removeAll(deletedOrMissing);
  }

  Future<void> _deleteUsedKeys() async {
    await Future.wait(
      usedKeys.toSet().map(
            (e) => deleteKey(e).onError((error, stackTrace) => false),
          ),
    );
  }
}

